MOD = 10**9 + 7

def transform(start, end):
    @lru_cache(maxsize=None)
    def dp(i, j):
        if i + (1 << j) < len(start):
            if start[i + (1 << j)] == '0':
                return max(dp(i, j + 1) + 2, dp(i + (1 << j), j))

            return max(dp(i, j + 1), dp(i + (1 << j), j) + 2)
        elif j < len(end) and end[j] == '0' and j - (1 << i) >= 0 and start[j - (1 << i)] == '1':
            if start[i] == '0':
                return max(dp(i, j + 1) + 2, dp(i + (1 << i), j))

            return max(dp(i + (1 << i), j), dp(i, j + 1) + 2)
        return dp(i + (1 << j), j + 1) + 1

    m = len(start)
    ans = 0
    for i in range(len(start)):
        for j in range(i + 1, m):
            if start[i] == '?' and end[j] == '?':
                ans = max(ans, dp(i, j) + 1)
            elif start[i] == '?' and end[j] != '?':
                ans = max(ans, dp(i, 0) + 2)
            elif start[i] != '?' and end[j] == '?':
                ans = max(ans, dp(0, j) + 2)
            else:
                ans = max(ans, dp(i, j) + 1)
    return ans % MOD

