from collections import defaultdict

def find_longest_good_sequence(N, A):
    sequence = [-1] * N
    longest = [0, 0]

    for index in range(N):
        char = A[index]
        if index == 0:
            if char == 1:
                sequence[index] = index + 1
                continue

        # Extend the current sequence by one place
        j = length = index
        while j < N and A[j] == char > 0:
            j += 1
            length += 1

        # If this length is already longer than the current longest
        if length > longest[1] - longest[0] + 1:
            longest = [index - length + 1, index]

        # If this length is identical to the current longest
        if length == longest[1] - longest[0] + 1:
            if A[j + 1] == char:
                longest = [index - length + 1, index]
                break

        sequence[index] = length + index + 1

    return longest

def main():
    T = int(input())
