def execute_query(query_str):
    ACTION, params = query_str.split()
    X, Y, N = map(int, params)

    # Perform XOR operations separately
    answer = (X ^ Y ^ N) & 0x01
    answer ^= (X >> 15) ^ (answer ^ 1) ^ (Y >> 15) ^ (answer ^ 3) ^ (Y << 15) ^ (answer ^ 7) ^ (X << 15) ^ (answer ^ 15) 

    # Answer logic based on XOR result
    if not (answer & 0x80):
        return '0'
    elif answer:
        return f'{(N >> 1) << 1} '
    elif answer:
        return f'{N << 1} '
    elif N:
        return f'{N + 1 << 1} '
    else:
        return str(N * 2 + 2)

