    valid = [False] * (k + 2)

    for i in range(n):
        for j in range(k):
            dp[j+2] = max(dp[j+2], dp[j]+intervals[i][1]-intervals[i][0])
            valid[j] = True
        if dp[k] >= sys.maxsize:
            break

    for j in range(k, 0, -1):
        if valid[j]:
            dp[j] += dp[k] - dp[j+1]
            valid[j+1] = True

