from collections import defaultdict

def dfs(node, parent, component_dict, visited, count, mod):
    visited[node] = True
    count[node] = 1
    component = [node]

    for neighbor in set(component_dict[node]) - {parent}:
        if visited[neighbor] == False:
            traverse = dfs(neighbor, node, component_dict, visited, count, mod)
            count[node] *= traverse + 1
            count[node] %= mod

    return count[node]

def solve(n, m, edges):
    if n <= 2:
        return n * (n - 1)

    component_dict = defaultdict(set)
    component_dict[1] = {1}
    visited = [False] * (n + 1)
    count = defaultdict(int)
    n_edges = 0

    for u, v in edges:
        component_dict[u].add(v)
        component_dict[v].add(u)
        n_edges += 1

    dfs(1, -1, component_dict, visited, count, 1000000007)

    for node in range(1, n + 1):
        if component_dict[node] and visited[node] == False:
            dfs(node, -1, component_dict, visited, count, 1000000007)

    path_count = 0

    for node in range(1, n + 1):
        count[node] = count[node] - (m - n_edges // 2) + 1
        path_count += (m - n_edges // 2) * count[node]

