from collections import defaultdict

def solve(n, m, queries):
    # Convert list of points and heights into adjacency list for Eulerian traversal
    graph = defaultdict(list)
    for a, b, c, d, w, h in queries:
        for k in range(h):
            graph[(a + 1, b + k, a + c, b + k + h)].append((c + k + 1, h + k, c + h + 1, b + h + k))
            graph[(a + c + k + 1, b + k, a + c + h + 1, b + h + k)].append((c + 1, h + 1, c + h + 1, b + k + h))

    # Eulerian proof: we need all nodes to be reachable and alternating must form sigma ω product
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            cond1 = isinstance(connected(graph, (i, j)), (set, frozenset))
            cond2 = any(map(lambda x: isinstance(connected(graph, x), set), graph[(i, j, i, j)]))
            if not (cond1 and cond2):
                raise ValueError(f'G{[i, j]} is not connected')

    # Eulerian traversal to find all Eulerian paths
    path = defaultdict(set)
    def eulerian_path():
        connections = [next(iter(graph[(i, j, i, j)]))]
        for k in range(n):
            yield connections
            next_connections = [next(iter(graph[(i, j, i + k, j)])) for i in range(1, n) if next(iter(graph[(i, j, i + k, j)]))]  # Skip connections passed so far
            connections = [connections[find(x, visited) % len(connections)] for x in next_connections]
            connections += next(iter(connections))
        yield next(iter(graph[(1, 1, n, m)]))

    for p in eulerian_path():
        for i, j in p:
            yield totals[get(i, j)]

    return '\n'.join(' '.join(map(str, v)) for v in totals)

def connected(graph, node):
    return list(next(iter(graph[node])))

def get(i, j):
    return i, i + j, i + j

