def lines_intersect(x1, y1, r1, x2, y2, r2):
    # calculate distance between the centers of two circles
    dist = math.sqrt((x1 - x2) ** 2 + (y1 - y2) ** 2)
    # calculate sum of radii
    sum_r = r1 + r2
    # condition for lines to intersect
    if dist > sum_r:
        return False
    elif dist == sum_r:
        return True
    else:
        r_angle_multiplied = r1 * r2 / dist
        tan = r2**2 - r1**2 + r1 * r2 * r2 / (2 * dist * sum_r * (dist - sum_r))
        # if the circle is completely covered we cannot perform any cutting line
        if r_angle_multiplied >= 1 - tan:
            return False
        return True

