class ST:
  def __init__(self, A):
    self.A = A
    self.l = max(self.A) + 1
    self.tree = [None] * (2 * self.l - 1)
    self.pushDown = [0] * (2 * self.l - 1)
    self.build(self.tree, 1, 1, len(A))

  def build(self, tree, pos, left, right):
    tree[pos] = self.heapify(0, pos, left, right)

  def heapify(self, index, tree, left, right):
    if left > right: return tree
    maxIndex = index
    if self.tree[2 * index + 1] > self.tree[maxIndex]: maxIndex = (2 * index + 1)
    if self.tree[2 * index + 2] > self.tree[maxIndex]: maxIndex = (2 * index + 2)
    if maxIndex < 2 * index + 2:
      temp = array[index]
      index = maxIndex
      tree[maxIndex] = tree[index]
      tree[index] = temp
    return tree

  def buildOp(self, tree, pos, left, right):
    if self.tree[pos] > 0:
      return
    if left < right:
      self.tree[pos] += self.tree[(pos << 1 | 1)]
      self.buildOp(tree, (pos << 1 | 1), left, (left + right) // 2)
      self.buildOp(tree, (pos << 1 | 2), ((left + right) // 2) + 1, right)

  def update(self, tree, pos, diff, left, right, mod):
    if left > right:
      return
    self.tree[pos] += diff
    self.pushDown[pos] += diff
    if mod > 0:
      return
    if left < right:
      self.buildOp(tree, (pos << 1 | 1), left, (left + right) // 2)
      self.buildOp(tree, (pos << 1 | 2), ((left + right) // 2) + 1, right)

  def _maxValue(self, tree, pos, left, right, a, b):
    if b <= left or right <= a:
      return float('-inf')
    elif a <= left <= right <= b:
      return tree[pos]
    else:
      lc = self._maxValue(tree, (pos << 1) + 1, left, ((left + right) // 2), a, b)
      rc = self._maxValue(tree, (pos << 1) + 2, ((left + right) // 2) + 1, right, a, b)
      return max(lc, rc)

  def query(self, tree, pos, left, right):
    if left == right:
      return tree[pos]
    maxValue = self._maxValue(self.tree, pos, left, right, left + 1, right + 1)
    self.pushDown[pos] = float('-inf')
    return maxValue + self.tree[pos]

