    dp[0][0] = 1

    for i in range(1, N + 1):
        dp[i][1] = dp[i - 1][1]
        if array[i - 1] == 1:
            dp[i][1] += 1
        for j in range(2, N + 1):
            if array[i - 1] == 1:
                dp[i][j] = dp[i - 1][j]
            if array[i - 1] == 0:
                dp[i][j] += dp[i - 1][j - 1]
            if dp[i][j] >= (j - 1):
                break
            dp[i][j] += dp[i - 1][j - 1]

    result = []
    for i in range(N):
        for j in range(i + 1, N + 1):
            if dp[i][j] >= (j - 1):
                while dp[i][j - 1] % (j - 1) == 0:
                    j -= 1
                result.append((i, j))
                dp[i][j] = 0
                dp[i + 1][j] += (j - 1)
                dp[i + 1][j - 1] += (j - 1)
                break

    return result, max(result, key=lambda x: (x[0], -x[1]))[0]

