from collections import defaultdict

def find_min_divisible_subsequence(k, nums):
    prefix_multiples = defaultdict(int)
    multiply_state = 1
    result_indices = []

    for i, num in enumerate(nums):
        multiply_state *= num
        if multiply_state % k != 0:
            continue

        product_count = 1
        product_index = -1

        for same_product_count, product_index_count in prefix_multiples.items():
            product = product_count * product_index_count
            if product_over(k, product):
                result_indices.append(product_index + 1)  # Convert index to index + 1 to match input format
                product_count += product_index_count
                prefix_multiples[product] = product_index_count - 1

        if not prefix_multiples:
            result_indices.append(i)
            prefix_multiples[multiply_state] = 1
        else:
            prefix_multiples[multiply_state] += 1

        if prefix_multiples[multiply_state] % 2 != 0:
            length = len(prefix_multiples)
            add_element(prefix_multiples, result_indices, length // 2)
            add_elements_to_outer(prefix_multiples, result_indices, length // 2)

    return result_indices

def product_over(n, k):
    return n % k == 0

def add_element(prefix_multiples, result_indices, product_count):
    if prefix_multiples[product_count] == 1:
        product_index = 0
    else:
        divisors = []
        for potential_divisor, existing_count in list(prefix_multiples.items()):
            if product_count % potential_divisor == 0 and existing_count > 0:
                new_count = existing_count - 1
                product_count //= potential_divisor
                prefix_multiples[potential_divisor] = new_count
                divisors.append((potential_divisor, new_count))

        for potential_divisor, existing_count in divisors:
            if product_count % potential_divisor == 0 and existing_count > 0:
                new_count = existing_count - 1
                prefix_multiples[potential_divisor] = new_count
                product_count //= potential_divisor
                add_element(prefix_multiples, result_indices, existing_count)

def add_elements_to_outer(prefix_multiples, result_indices, product_count):
    add_element(prefix_multiples, result_indices, product_count)

