from typing import List

def update_matrix(matrix: List[List[int]], task: List[int]):
    """
    Update the matrix based on given task.
    """
    for i in range(task[0], task[2]+1):
        for j in range(task[3], task[5]+1, 2):
            matrix[i][j] ^= 1  # Toggle the cell's value
            matrix[i][j+1] ^= 1
    return matrix

def swap_rectangles(matrix: List[List[int]], rect1, rect2: List[int]):
    """
    Swap the two rectangles in the matrix.
    """
    returned_matrix = [row[:] for row in matrix]
    for i in range(rect1[0], rect1[2]+1):
        for j in range(rect1[3], rect1[5]+1, 2):
            returned_matrix[i][j] ^= 1  # Toggle the cells in the first rectangle
            returned_matrix[i][j+1] ^= 1
    for i in range(rect2[0], rect2[2]+1):
        for j in range(rect2[3], rect2[5]+1, 2):
            returned_matrix[i][j] ^= 1  # Toggle the cells in the second rectangle
            returned_matrix[i][j+1] ^= 1
    return returned_matrix

def process_tasks(matrix: List[List[int]], tasks: List[List[int]]):
    """
    Process all tasks on the matrix.
    """
    for task in tasks:
        matrix = swap_rectangles(matrix, (task[0], task[1], task[2], task[3], task[4], task[5]))
    return matrix

