import math

def find_min_divisible_sequence(n, k, a):
    a_len = len(a)
    sequence_length = int(math.log2(k)) if k <= 1 else int(math.log2(n))
    minimum_cost = math.inf
    min_subset_sum = float('inf')
    visited = [False] * n
    min_subset = []

    def backtrack(i, current_cost, current_length, current_sum):
        nonlocal minimum_cost, min_subset_sum, min_subset
        if current_length > sequence_length:
            return
        if current_cost > minimum_cost:
            return
        if current_cost == minimum_cost and current_sum > min_subset_sum:
            return
        if current_length == sequence_length:
            if current_cost < minimum_cost or (current_cost == minimum_cost and current_sum < min_subset_sum):
                min_subset = min_subset_sum = current_sum
            return
        if current_length > sequence_length:
            return
        if current_length > 1 and visited[i]:
            backtrack(i-1, current_cost, current_length, current_sum)
        if i < n-1:
            if a[i+1] % k == 0 and current_cost < minimum_cost or (current_cost == minimum_cost and current_sum < min_subset_sum):
                visited[i] = True
                backtrack(i+1, current_cost, current_length+1, current_sum+a[i])
                visited[i] = False

    backtrack(0, 0, 0, 0)
    if min_subset < float('inf'):
        for i in min_subset:
            print(i, end=' ')
        print()
    else:
        print(-1)

