from itertools import accumulate

def inclusive_xor(A):
    """Find the maximum bitwise XOR value within the range [left, right] of an array A."""
    right_most = 1
    result = 0
    for i in range(len(A) - 1, -1, -1):
        if A[i] >= right_most:
            right_most <<= 1
            right_most -= 1
        else:
            result |= (A[i] & 1) << i
    return result

def max_value_of_intervals(intervals, k):
    n = len(intervals)
    sorted_intervals = sorted(range(n), key=lambda i: intervals[i][0])
    values = [0] * n

    for i in range(n):
        values[sorted_intervals[i]] = intervals[i][1] - intervals[sorted_intervals[i]][0] + 1

    cumulative_sum = list(accumulate(values))
    maximum_xor = 0
    total_intervals = sum(intervals[i][1] - intervals[i][0] + 1 for i in range(n))

    for max_index in range(2**max(total_intervals - k + 1, k)):
        max_pos_bits_list = list(format(max_index, '0%db' % max(total_intervals - k + 1, k)))
        if ''.join([str(char) for char in max_pos_bits_list[total_intervals - k + 1:]]).upper() == "B":
            continue

        start = -1
        end = 0
        bits_used = 0

        for i in range(n):
            length = max(0, len(cumulative_sum) - 1 - i)
            interval_value = cumulative_sum[length] - cumulative_sum[max(start, end)]
            xor_value = (interval_value ^ cumulative_sum[-1] ^ cumulative_sum[i]) & max_pos_bits_list[length]
            xor_mask = inclusive_xor(cumulative_sum, end + 1, x=2 * xor_value)
            for j in range(k):
                if not max_pos_bits_list[length + j] & xor_mask:
                    break
                else:
                    if j == k - 1:
                        length += 1
                        start, end = max(end, max_pos_bits_list[length] // 2 - 1), max_end + 1

        for i in range(k):
            xor_mask = (1 << i) - 1
            for j in range(start, min(end + 1, n)):
                mask = sorted_intervals[j] ^ xor_mask
                if next((i for i in max_pos_bits_list if max_pos_bits_list[i] & mask), -1) == -1:
                    break
            else:
                maximum_xor = max(maximum_xor, interval_value ^ cumulative_sum[-1] ^ cumulative_sum[j - 1] ^ cumulative_sum[j])

    return maximum_xor

