from collections import defaultdict

def find_longest_good_sequence(N, binary_array):
    dp = [0]*N
    # Count of ones in each prefix
    prefix_ones = 0
    max_length = 0

    for i in range(N):
        if binary_array[i] == 1:
            prefix_ones += 1
        dp[i] = i + 1 - prefix_ones  # The maximum number of ones in any subarray ending at i

    max_diff = 0
    longest_sequence = []
    for i in range(N):
        if dp[max_length] - dp[len(binary_array) - 1] < len(binary_array) - i:
            max_diff = dp[max_length] - dp[len(binary_array) - 1]
        if dp[max_length] - dp[i] >= max_diff:
            longest_sequence = [i]
        elif dp[i] - dp[max_length] >= max_diff:
            longest_sequence = [len(binary_array) - dp[max_length + i], len(binary_array) - dp[i]]
            max_diff = longest_sequence[0] - longest_sequence[1]

    return len(longest_sequence), *sorted(longest_sequence)

