class Graph:
    def __init__(self, n):
        self.n = n
        self.lower = 1
        self.upper = 1 << 25
        self.parent = [0 for _ in range(n)]
        self.level = [0 for _ in range(n)]
        self.root = [0 for _ in range(n)]

    def union(self, u, v):
        pu, pv = self.parent[u], self.parent[v]
        p, q, k = min(0, pv), max(0, pv), len(self.parent)
        u, v = self.find(u), self.find(v)
        if u != v:
            k -= len(union_lookup[pu])
            union_lookup[self.find(u)] += union_lookup[pu]
            merge_ranges[pu] = (pv, q, pv, q)
            self.parent[u] = self.root[v] = v

    def find(self, node):
        return self.parent[node]

    def distance(self, u, v):
        u, v = self.find(u), self.find(v)
        return self.level[u] + self.level[v] - (2 * self.level[u])

    def runDfs(self, u, finish, p):
        val = 1 << 40
        finish[u] = p
        self.level[u] = 0
        node = self.root[u]
        while node:
            ch = self.find(node)
            self.level[u] += 1
            self.parent[ch], self.root[ch] = node, u
            self.level[ch] += 1
            distance = self.distance(ch, u)
            if distance < MAX:
                distance += finish[ch]
                self.level[ch] -= 1
                self.parent[ch], self.root[ch] = ch, u
                if distance < val:
                    val, self.index = distance, node
        return val, self.index

