import numpy as np

class PointSet:
    def __init__(self):
        self.points = []
        self.values = []

    def add_point(self, x, y):
        point = (x, y)
        if point not in self.points:
            self.points.append(point)
            self.values.append(x | y)

    def remove_point(self, id):
        new_values = []
        for i, (x, y) in enumerate(zip(self.values, self.points)):
            if i == id:
                continue
            new_values.append((x ^ self.values[id], y ^ self.values[id]))
        self.values = new_values
        self.points = [p for i, p in enumerate(zip(self.values, self.points)) if i != id]

    def max_manhattan_distance(self, x, y):
        new_values = []
        new_points = []
        for i, (x_, y_) in enumerate(zip(self.values, self.points)):
            for operation in [lambda v: (x | v, y | v), lambda v: (v ^ x, y | v), lambda v: (x | v, v ^ y), lambda v: (v ^ x, v ^ y)]:
