import sys

def find_min_distance(points):
    # Calculate the Euclidean distance between two points
    def dist(p1, p2):
        return ((p1[0] - p2[0]) ** 2 + (p1[1] - p2[1]) ** 2) ** 0.5

    n = len(points)
    route = sorted(points, key=lambda x: ((x[0], x[1])))
    left = 0
    right = 50  # A large initial distance to iterate on

    while left < right:
        mid = (left + right) / 2
        if is_possible(route, mid):
            right = mid
        else:
            left = mid + 1

    return left

def is_possible(route, distance):
    n = len(route)
    prev_vertex = None
    last_time = 0

    for i in range(n):
        for j in range(i + 1, n + i):
            time_saved = dist(route[i], route[j - 1]) / (2 * distance)
            if abs(last_time - time_saved) > 1e-6:
                if i + 1 < n:
                    return False
            if i == 0:
                prev_vertex = route[i]
            else:
                dist_to_prev = dist(route[i], route[i - 1])
                if dist_to_prev > distance:
                    return False
            last_time = time_saved

    return True

points = []
while True:
    try:
        x, y = map(int, input().split())
        points.append((x, y))
    except EOFError:
        break

min_d = find_min_distance(points)
print(min_d)
